    function openDocumentModal() { const modal = openModal({ title: '新建受控文件', size: 'md', body: `<div class="form-row"><div class="form-group"><label class="form-label">文件号 *</label><input id="dcNo" class="input-field"></div><div class="form-group"><label class="form-label">类型 *</label><select id="dcType" class="input-field"><option>POLICY</option><option>SOP</option><option>FORM</option><option>SPECIFICATION</option><option>RECORD_TEMPLATE</option></select></div></div><div class="form-row"><div class="form-group"><label class="form-label">标题 *</label><input id="dcTitle" class="input-field"></div><div class="form-group"><label class="form-label">部门 *</label><input id="dcDept" class="input-field"></div></div><div class="form-group"><label class="form-label">文件负责人 *</label><select id="dcOwner" class="input-field">${userOptions()}</select></div><div class="form-group"><label class="form-label">原因 *</label><textarea id="dcReason" class="input-field"></textarea></div>`, footer: '<button class="btn btn-secondary" data-close>取消</button><button class="btn btn-primary" id="dcSubmit">保存</button>' }); modal.querySelector('#dcSubmit').addEventListener('click', async () => { const body = { document_no: modal.querySelector('#dcNo').value.trim(), title: modal.querySelector('#dcTitle').value.trim(), document_type: modal.querySelector('#dcType').value, department: modal.querySelector('#dcDept').value.trim(), owner_id: Number(modal.querySelector('#dcOwner').value), reason: modal.querySelector('#dcReason').value.trim() }; if (!body.document_no || !body.title || !body.department || !body.owner_id || body.reason.length < 3) return showToast('请完整填写', 'warning'); try { await api('/gsp/quality-system/documents', { method: 'POST', body }); closeModal(modal); await loadTab(); } catch (e) { showToast(e.message, 'error'); } }); }
    function newRevision(documentId) { const modal = openModal({ title: '新建文件修订', size: 'md', body: '<div class="form-row"><div class="form-group"><label class="form-label">版本 *</label><input id="drVersion" class="input-field"></div><div class="form-group"><label class="form-label">生效日期 *</label><input type="date" id="drDate" class="input-field"></div></div><div class="form-group"><label class="form-label">变更摘要 *</label><textarea id="drSummary" class="input-field"></textarea></div><div class="form-group"><label class="form-label">内容引用 *</label><input id="drRef" class="input-field"></div><div class="form-group"><label class="form-label">内容SHA-256 *</label><input id="drHash" class="input-field" maxlength="64"></div><div class="form-group"><label class="form-label">原因 *</label><textarea id="drWhy" class="input-field"></textarea></div>', footer: '<button class="btn btn-secondary" data-close>取消</button><button class="btn btn-primary" id="drSave">保存</button>' }); modal.querySelector('#drSave').addEventListener('click', async () => { const body = { version: modal.querySelector('#drVersion').value.trim(), change_summary: modal.querySelector('#drSummary').value.trim(), content_ref: modal.querySelector('#drRef').value.trim(), content_sha256: modal.querySelector('#drHash').value.trim().toLowerCase(), effective_date: modal.querySelector('#drDate').value, reason: modal.querySelector('#drWhy').value.trim() }; if (!body.version || !body.change_summary || !body.content_ref || !/^[0-9a-f]{64}$/.test(body.content_sha256) || !body.effective_date || body.reason.length < 3) return showToast('请填写完整内容及64位SHA-256', 'warning'); try { await api(`/gsp/quality-system/documents/${documentId}/revisions`, { method: 'POST', body }); closeModal(modal); await loadTab(); } catch (e) { showToast(e.message, 'error'); } }); }
