    function issueCopy(revisionId) { const modal = openModal({ title: '发放受控副本', size: 'md', body: '<div class="form-row"><div class="form-group"><label class="form-label">唯一份号 *</label><input id="diNo" class="input-field"></div><div class="form-group"><label class="form-label">持有人 *</label><input id="diHolder" class="input-field"></div></div><div class="form-group"><label class="form-label">使用位置 *</label><input id="diLocation" class="input-field"></div><div class="form-group"><label class="form-label">用途 *</label><input id="diPurpose" class="input-field"></div><div class="form-group"><label class="form-label">原因 *</label><textarea id="diReason" class="input-field"></textarea></div>', footer: '<button class="btn btn-secondary" data-close>取消</button><button class="btn btn-primary" id="diSubmit">发放</button>' }); modal.querySelector('#diSubmit').addEventListener('click', async () => { const body = { copy_no: modal.querySelector('#diNo').value.trim(), holder: modal.querySelector('#diHolder').value.trim(), location: modal.querySelector('#diLocation').value.trim(), purpose: modal.querySelector('#diPurpose').value.trim(), reason: modal.querySelector('#diReason').value.trim() }; if (!body.copy_no || !body.holder || !body.location || !body.purpose || body.reason.length < 3) return showToast('请完整填写', 'warning'); try { await api(`/gsp/quality-system/documents/revisions/${revisionId}/copies`, { method: 'POST', body }); closeModal(modal); await loadTab(); } catch (e) { showToast(e.message, 'error'); } }); }
    function disposeCopy(id) { const modal = openModal({ title: '回收或销毁受控副本', size: 'sm', body: '<div class="form-group"><label class="form-label">处置 *</label><select id="ddAction" class="input-field"><option value="RETURN">回收</option><option value="DESTROY">销毁</option></select></div><div class="form-group"><label class="form-label">证据引用 *</label><input id="ddRef" class="input-field"></div><div class="form-group"><label class="form-label">原因 *</label><textarea id="ddReason" class="input-field"></textarea></div>', footer: '<button class="btn btn-secondary" data-close>取消</button><button class="btn btn-primary" id="ddSubmit">确认</button>' }); modal.querySelector('#ddSubmit').addEventListener('click', async () => { const body = { action: modal.querySelector('#ddAction').value, evidence_ref: modal.querySelector('#ddRef').value.trim(), reason: modal.querySelector('#ddReason').value.trim() }; if (!body.evidence_ref || body.reason.length < 3) return showToast('请完整填写', 'warning'); try { await api(`/gsp/quality-system/documents/copies/${id}/dispose`, { method: 'POST', body }); closeModal(modal); await loadTab(); } catch (e) { showToast(e.message, 'error'); } }); }

    function renderEquipment(box) {
        box.innerHTML = `<div class="card"><div class="card-header"><span class="card-title">设施设备验证与校准总台账</span><button class="btn btn-primary" id="eqNew">新建设备</button></div><div class="card-body p-0 table-wrap"><table class="data-table"><thead><tr><th>编号</th><th>名称</th><th>类别</th><th>位置</th><th>关键程度</th><th>下次验证</th><th>下次校准</th><th>状态</th><th class="actions">操作</th></tr></thead><tbody>${(cache.equipment || []).map(e => `<tr><td>${esc(e.equipment_no)}</td><td>${esc(e.name)}</td><td>${esc(e.category)}</td><td>${esc(e.location)}</td><td>${badge(e.criticality, ['HIGH','CRITICAL'].includes(e.criticality) ? 'danger' : 'warning')}</td><td>${fmtD(e.next_qualification_date)}</td><td>${fmtD(e.next_calibration_date)}</td><td>${statusBadge(e.status)}</td><td class="actions">${e.status === 'PENDING' ? `<button class="btn btn-link btn-sm" onclick="PG('qms').approveEquipment(${e.id})">批准</button>` : ''}${['APPROVED','OUT_OF_SERVICE','QUALIFICATION_PENDING'].includes(e.status) ? `<button class="btn btn-link btn-sm" onclick="PG('qms').newActivity(${e.id})">登记活动</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="9"><div class="empty-state">暂无设施设备</div></td></tr>'}</tbody></table></div></div><div class="card mt-3"><div class="card-header"><span class="card-title">验证/校准/维护活动</span></div><div class="card-body p-0 table-wrap"><table class="data-table"><thead><tr><th>活动号</th><th>设备</th><th>类型</th><th>执行日期</th><th>有效期</th><th>机构</th><th>结果</th><th>状态</th><th class="actions">操作</th></tr></thead><tbody>${(cache.activities || []).map(a => `<tr><td>${esc(a.activity_no)}</td><td>#${a.equipment_id}</td><td>${esc(a.activity_type)}</td><td>${fmtD(a.performed_on)}</td><td>${fmtD(a.valid_to)}</td><td>${esc(a.provider)}</td><td>${esc(a.result)}</td><td>${statusBadge(a.status)}</td><td class="actions">${a.status === 'PENDING_REVIEW' ? `<button class="btn btn-link btn-sm" onclick="PG('qms').reviewActivity(${a.id})">复核${a.result === 'FAILED' ? '并停用' : ''}</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="9"><div class="empty-state">暂无设备活动</div></td></tr>'}</tbody></table></div></div>`;
        box.querySelector('#eqNew').addEventListener('click', openEquipmentModal);
    }
    function openEquipmentModal() { const modal = openModal({ title: '新建设施设备', size: 'md', body: '<div class="form-row"><div class="form-group"><label class="form-label">编号 *</label><input id="qeNo" class="input-field"></div><div class="form-group"><label class="form-label">名称 *</label><input id="qeName" class="input-field"></div></div><div class="form-row"><div class="form-group"><label class="form-label">类别 *</label><input id="qeCategory" class="input-field"></div><div class="form-group"><label class="form-label">位置 *</label><input id="qeLocation" class="input-field"></div></div><div class="form-group"><label class="form-label">关键程度 *</label><select id="qeCritical" class="input-field"><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select></div><div class="flex gap-3"><label class="checkbox-label"><input type="checkbox" id="qeQual" checked> 需要验证</label><label class="checkbox-label"><input type="checkbox" id="qeCal"> 需要校准</label></div><div class="form-group"><label class="form-label">原因 *</label><textarea id="qeReason" class="input-field"></textarea></div>', footer: '<button class="btn btn-secondary" data-close>取消</button><button class="btn btn-primary" id="qeSubmit">保存</button>' }); modal.querySelector('#qeSubmit').addEventListener('click', async () => { const body = { equipment_no: modal.querySelector('#qeNo').value.trim(), name: modal.querySelector('#qeName').value.trim(), category: modal.querySelector('#qeCategory').value.trim(), location: modal.querySelector('#qeLocation').value.trim(), criticality: modal.querySelector('#qeCritical').value, qualification_required: modal.querySelector('#qeQual').checked, calibration_required: modal.querySelector('#qeCal').checked, reason: modal.querySelector('#qeReason').value.trim() }; if (!body.equipment_no || !body.name || !body.category || !body.location || body.reason.length < 3) return showToast('请完整填写', 'warning'); try { await api('/gsp/quality-system/equipment', { method: 'POST', body }); closeModal(modal); await loadTab(); } catch (e) { showToast(e.message, 'error'); } }); }
    function approveEquipment(id) { reasonAction({ title: '批准设备档案', path: `/gsp/quality-system/equipment/${id}/approve`, signature: { action: 'QUALITY_EQUIPMENT_APPROVE', entity_type: 'GspQualityEquipment', entity_id: id, meaning: 'APPROVAL' }, success: '设备档案已批准' }); }
    function newActivity(equipmentId) { const modal = openModal({ title: '登记设备活动', size: 'md', body: '<div class="form-row"><div class="form-group"><label class="form-label">活动号 *</label><input id="eaNo" class="input-field"></div><div class="form-group"><label class="form-label">类型 *</label><select id="eaType" class="input-field"><option>QUALIFICATION</option><option>CALIBRATION</option><option>MAINTENANCE</option></select></div></div><div class="form-row"><div class="form-group"><label class="form-label">执行日期 *</label><input type="date" id="eaDate" class="input-field"></div><div class="form-group"><label class="form-label">有效期</label><input type="date" id="eaValid" class="input-field"></div></div><div class="form-group"><label class="form-label">服务机构 *</label><input id="eaProvider" class="input-field"></div><div class="form-group"><label class="form-label">证书/报告引用 *</label><input id="eaRef" class="input-field"></div><div class="form-group"><label class="form-label">结果 *</label><select id="eaResult" class="input-field"><option>PASSED</option><option>FAILED</option></select></div><div class="form-group"><label class="form-label">原因 *</label><textarea id="eaReason" class="input-field"></textarea></div>', footer: '<button class="btn btn-secondary" data-close>取消</button><button class="btn btn-primary" id="eaSubmit">保存</button>' }); modal.querySelector('#eaSubmit').addEventListener('click', async () => { const body = { activity_no: modal.querySelector('#eaNo').value.trim(), activity_type: modal.querySelector('#eaType').value, performed_on: modal.querySelector('#eaDate').value, valid_to: modal.querySelector('#eaValid').value || null, provider: modal.querySelector('#eaProvider').value.trim(), certificate_ref: modal.querySelector('#eaRef').value.trim(), result: modal.querySelector('#eaResult').value, reason: modal.querySelector('#eaReason').value.trim() }; if (!body.activity_no || !body.performed_on || !body.provider || !body.certificate_ref || body.reason.length < 3 || (['QUALIFICATION','CALIBRATION'].includes(body.activity_type) && !body.valid_to)) return showToast('请完整填写', 'warning'); try { await api(`/gsp/quality-system/equipment/${equipmentId}/activities`, { method: 'POST', body }); closeModal(modal); await loadTab(); } catch (e) { showToast(e.message, 'error'); } }); }
    function reviewActivity(id) { reasonAction({ title: '复核设备活动', path: `/gsp/quality-system/equipment/activities/${id}/review`, signature: { action: 'EQUIPMENT_ACTIVITY_REVIEW', entity_type: 'GspEquipmentActivity', entity_id: id, meaning: 'REVIEW' }, success: '设备活动已复核' }); }

    function renderScopes(box) {
        box.innerHTML = `<div class="card"><div class="card-header"><span class="card-title">特殊管理药品/疫苗经营范围授权</span><button class="btn btn-primary" id="scopeNew">新建授权</button></div><div class="card-body"><div class="alert alert-warning mb-3">品种选择特殊管理药品或疫苗后，必须存在有效且独立批准的经营范围授权，否则品种批准、采购和销售均被阻断。</div><div class="table-wrap"><table class="data-table"><thead><tr><th>类别</th><th>授权编号</th><th>授权引用</th><th>有效期</th><th>控制摘要</th><th>状态</th><th class="actions">操作</th></tr></thead><tbody>${(cache.scopes || []).map(s => `<tr><td>${badge(s.category, 'danger')}</td><td>${esc(s.authorization_no)}</td><td>${esc(s.authorization_ref)}</td><td>${fmtD(s.valid_to)}</td><td>${esc(s.controls_summary)}</td><td>${statusBadge(s.status)}</td><td class="actions">${s.status === 'PENDING' ? `<button class="btn btn-link btn-sm" onclick="PG('qms').approveScope(${s.id})">批准</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="7"><div class="empty-state">尚未批准特殊管理药品或疫苗经营范围；相关品种默认禁止经营</div></td></tr>'}</tbody></table></div></div></div>`;
        box.querySelector('#scopeNew').addEventListener('click', openScopeModal);
    }
    function openScopeModal() { const modal = openModal({ title: '新建专项经营范围', size: 'md', body: '<div class="form-row"><div class="form-group"><label class="form-label">类别 *</label><select id="qsCategory" class="input-field"><option value="SPECIAL_CONTROLLED">特殊管理药品</option><option value="VACCINE">疫苗</option></select></div><div class="form-group"><label class="form-label">授权编号 *</label><input id="qsNo" class="input-field"></div></div><div class="form-row"><div class="form-group"><label class="form-label">授权引用 *</label><input id="qsRef" class="input-field"></div><div class="form-group"><label class="form-label">有效期 *</label><input type="date" id="qsValid" class="input-field"></div></div><div class="form-group"><label class="form-label">控制摘要 *</label><textarea id="qsControls" class="input-field"></textarea></div><div class="form-group"><label class="form-label">原因 *</label><textarea id="qsReason" class="input-field"></textarea></div>', footer: '<button class="btn btn-secondary" data-close>取消</button><button class="btn btn-primary" id="qsSubmit">保存</button>' }); modal.querySelector('#qsSubmit').addEventListener('click', async () => { const body = { category: modal.querySelector('#qsCategory').value, authorization_no: modal.querySelector('#qsNo').value.trim(), authorization_ref: modal.querySelector('#qsRef').value.trim(), valid_to: modal.querySelector('#qsValid').value, controls_summary: modal.querySelector('#qsControls').value.trim(), reason: modal.querySelector('#qsReason').value.trim() }; if (!body.authorization_no || !body.authorization_ref || !body.valid_to || !body.controls_summary || body.reason.length < 3) return showToast('请完整填写', 'warning'); try { await api('/gsp/quality-system/regulated-scopes', { method: 'POST', body }); closeModal(modal); await loadTab(); } catch (e) { showToast(e.message, 'error'); } }); }
    function approveScope(id) { reasonAction({ title: '批准专项经营范围', path: `/gsp/quality-system/regulated-scopes/${id}/approve`, signature: { action: 'REGULATED_SCOPE_APPROVE', entity_type: 'GspRegulatedScopeAuthorization', entity_id: id, meaning: 'APPROVAL' }, success: '专项经营范围已批准' }); }

    window.PAGES = window.PAGES || {};
    window.PAGES['qms'] = {
        title: '质量体系管理', icon: 'fa-check-square-o', desc: '年度评审、风险/CAPA、培训、文件和设备验证', init: pageInit,
        fn: { submitReview, decideReview, closeReview, submitRisk, reviewRisk, newCapa, implementCapa, verifyCapa, investigateEvent, closeEvent, completeTraining, verifyTraining, newRevision, submitRevision, approveRevision, issueCopy, disposeCopy, approveEquipment, newActivity, reviewActivity, approveScope },
    };
